query ShopMenusQuery($channel: String!, $footerSlug: String!, $mainMenuSlug: String!) {
  footer: menu(channel: $channel, slug: $footerSlug) {
    id
    items {
      ...MenuItem
      children {
        ...MenuItem
      }
    }
  }
  mainMenu: menu(channel: $channel, slug: $mainMenuSlug) {
    items {
      ...MenuItem
      children {
        ...MenuItem
        children {
          ...MenuItem
        }
      }
    }
  }
}

fragment MenuItem on MenuItem {
  id
  name
  category {
    id
    name
    slug
  }
  url
  collection {
    id
    name
    slug
  }
  page {
    slug
  }
  parent {
    id
  }
}
